insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 12, 'E ele confirmou sua palavra que falou sobre nós, e sobre nossos juízes que nos julgavam, trazendo sobre nós tão grande mal, que nunca havia sido feito debaixo do céu como o que foi feito em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 13, 'Assim como está escrito na Lei de Moisés, todo aquele mal veio sobre nós; contudo não suplicamos à face do SENHOR nosso Deus, para nos convertermos de nossas maldades, e entender a tua verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 14, 'O SENHOR vigiou sobre o mal, e o trouxe sobre nós; porque justo é o SENHOR nosso Deus em todas suas obras que fez; pois não obedecemos a sua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 15, 'Agora pois, ó Senhor nosso Deus, que tiraste teu povo da terra do Egito com mão poderosa, e fizeste famoso o teu nome até hoje; temos pecado, agimos com maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 16, 'Ó Senhor, segundo todas tuas justiças, desvie agora tua ira e teu furor de sobre a tua cidade Jerusalém, teu santo monte; pois por causa de nossos pecados, e pela maldades de nossos pais, Jerusalém e teu povo foram humilhados por todos os que estão ao nosso redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 17, 'Agora pois, ó Deus nosso, ouve a oração de teu servo, e suas súplicas, e faze que teu rosto resplandeça sobre teu santuário assolado, por causa do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 18, 'Inclina, ó Deus meu, teus ouvidos, e ouve; abre teus olhos, e olha para nossas assolações, e para a cidade que é chamada pelo teu nome; pois não apresentamos nossas súplicas diante de ti [confiando] em nossas justiças, mas sim em tuas muitas misericórdias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 19, 'Ouve, Senhor; ó Senhor, perdoa; presta atenção, Senhor, e faze sem demorar, por causa de ti mesmo, Deus meu; pois a tua cidade e teu povo são chamados pelo teu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 20, 'Enquanto eu ainda estava falando e orando, e confessando meu pecado e o pecado de meu povo Israel, e apresentando minha súplica diante do SENHOR meu Deus, pelo monte santo de meu Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 21, 'Estava eu falando em oração, e aquele varão Gabriel, ao qual eu tinha visto em visão antes, veio voando apressadamente, e me tocou cerca da hora do sacrifício da tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 22, 'E [me] explicou, e falou comigo, dizendo: Daniel, agora saí para te fazer entender o sentido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 23, 'No princípio de tuas súplicas a palavra saiu, e eu vim para te declarar, pois tu és muito querido. Considera, pois a palavra, e entende a visão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 24, 'Setenta semanas estão determinadas sobre teu povo e sobre tua santa cidade, para acabar a transgressão, para encerrar o pecado, para expiar a maldade, e para trazer a justiça eterna; para selar a visão e a profecia, e para ungir o Santo dos santos'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 25, 'Sabe pois e entendas: desde a saída da palavra para restaurar e edificar a Jerusalém até o Messias, o Príncipe, haverá sete semanas, e sessenta e duas semanas; voltará a ser construída com praças e muro, porém em tempos angustiosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 26, 'E depois das sessenta e duas semanas o Messias será exterminado, e nada terá para si; e o povo do príncipe que virá destruirá à cidade e o santuário; o fim dela será com inundação, e até o fim da guerra estão determinadas assolações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 27, 'E firmará um pacto com muitos por uma semana; e na metade da semana fará cessar o sacrifício e a oferta de alimentos; depois sobre a asa das abominações será o assolador, e isto até que seja derramado o fim determinado sobre o assolador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 1, 'No terceiro ano de Ciro rei da Pérsia, foi revelada uma palavra a Daniel, cujo nome era chamado Beltessazar; e a palavra é verdadeira, e sobre uma grande guerra; e ele entendeu a palavra, e teve entendimento da visão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 2, 'Naqueles dias eu, Daniel, me entristeci durante três semanas completas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 3, 'Não comi alimento agradável, nem carne nem vinho entrou em minha boca, nem me untei com unguento, até que se completassem três semanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 4, 'E aos vinte e quatro dias do primeiro mês, estava eu na margem do grande rio Tigre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 5, 'Então levantei meus olhos, e olhei, e eis um homem vestido de linho, e cingidos seus lombos de ouro fino de Ufaz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 6, 'E seu corpo era como berilo, seu rosto parecia um relâmpago; seus olhos eram como tochas de fogo, e seus braços e seus pés como de cor de bronze polido; e a voz de suas palavras era como a voz de uma multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 7, 'E somente eu, Daniel, vi aquela visão, e os homens que estavam comigo não a viram; porém caiu sobre eles um grande temor, de tal modo que fugiram e se esconderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 8, 'Fiquei, pois, eu só, e vi esta grande visão, e não ficou em mim força alguma; antes minha boa aparência se tornou em palidez, sem reter força alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 9, 'Porém ouvi a voz de suas palavras; e enquanto ouvia a voz de suas palavras, eu caí em profundo sono sobre meu rosto, com meu rosto em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 10, 'E eis que uma mão me tocou, e fez que eu me movesse sobre meus joelhos, e sobre as palmas de minhas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 11, 'E disse-me: Daniel, homem muito querido, entende as palavras que falarei contigo, e levanta-te sobre teus pés; porque agora sou enviado a ti. E enquanto ele falava comigo esta palavra, eu estava tremendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 12, 'E ele me disse: Não temas, Daniel; porque desde o primeiro dia em que deste teu coração a entender, e a te afligir na presença de teu Deus, foram ouvidas tuas palavras; e foi por causa de tuas palavras que eu vim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 13, 'Mas o príncipe do reino da Pérsia se pôs contra mim por vinte e um dias; e eis que Miguel, um dos principais chefes, veio para me ajudar, e eu fiquei ali com os reis da Pérsia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 14, 'Agora vim para te fazer entender o que irá acontecer a teu povo nos últimos dias; porque a visão ainda é para [muitos] dias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 15, 'E tendo ele falado comigo estas palavras, abaixei meu rosto em terra, e emudeci.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 16, 'E eis que [alguém] semelhante aos filhos dos homens tocou meus lábios. Então abri minha boca, e falei, e disse ao que estava diante de mim: Meu senhor, por causa da visão minhas dores se tornam sobre mim, sem que eu retenha força alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 17, 'Como pode, pois, o servo de meu senhor falar com este meu senhor? Pois desde agora não resta força em mim, e não me ficou fôlego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 18, 'E [aquele] que parecia com um homem me tocou outra vez, e me confortou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 19, 'E disse: Não temas, homem querido, paz seja contigo; sê forte! Sê forte! E tendo ele falado comigo, fortaleci-me, e disse: Fale meu senhor, pois tu me fortaleceste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 20, 'E ele disse: Sabes por que vim ti? Pois agora voltarei para lutar contra o príncipe da Pérsia; e quando eu sair, eis que virá o príncipe da Grécia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 10, 21, 'Porém eu te declararei o que está escrito na escritura de verdade; e ninguém há que se esforce comigo contra eles, a não ser Miguel, vosso príncipe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 1, 'E eu, no primeiro ano de Dario o medo, estive para confortá-lo e fortalecê-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 2, 'E agora eu te declararei a verdade. Eis que ainda haverá três reis na Pérsia, e o quarto acumulará mais riquezas que todos; e fortificando-se com suas riquezas, despertará a todos contra o reino da Grécia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 3, 'Depois se levantará um rei poderoso, que reinará com grande domínio, e fará conforme sua vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 4, 'Mas quando ele estiver erguido, seu reino será quebrantado, e repartido nos quatro ventos do céu; porém não a seus descendentes, nem conforme seu domínio com que ele reinou; porque seu reino será arrancado, e será para outros fora destes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 5, 'E o rei do sul se fortalecerá; mas um de seus príncipes se fortalecerá mais que ele, e reinará; e seus domínio será um grande domínio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 6, 'Mas ao fim de [alguns] anos eles se aliarão, e a filha do rei do sul virá ao rei do norte para fazer os acordos. Porém ela não poderá reter a força de seu poder; por isso nem ele, nem seu poder persistirá; porque ela será entregue, e os que a tiverem trazido, e seu pai, e ao que a fortalecia naqueles tempos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 7, 'Mas do renovo de suas raízes um se levantará em seu lugar; e virá com exército, e entrará na fortaleza do rei do norte, e agirá contra eles, e prevalecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 8, 'E até seus deuses com seus príncipes, com seus vasos preciosos de prata e de ouro, levará cativos ao Egito; e por [alguns] anos ele deixará de atacar o rei do norte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 9, 'O qual virá ao reino o rei do sul, e voltará para sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 10, 'Porém os filhos dele se agitarão [para a guerra] ,e ajuntarão uma multidão de grandes exércitos; e certamente avançará, inundará, e passará; e quando voltar, se agitará [em guerra] até sua fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 11, 'Então o rei do sul se enfurecerá, e sairá, e lutará contra ele, o rei do norte; e mobiliza uma grande multidão, porém toda aquela multidão será entregue em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 12, 'Quando for perdida aquele multidão, seu coração se exaltará; e ainda que derrube muitos milhares; contudo não prevalecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 13, 'E o rei do norte voltará, e porá em campo uma multidão maior que a primeira, e a fim do tempo de [alguns] anos avançará com grande exército e com muitos suprimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 14, 'E naqueles tempos muitos se levantarão contra o rei do sul; e filhos dos violentos de teu povo se levantarão para confirmar a visão, e cairão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 15, 'Então o rei do norte virá, e levantará cerco, e tomará a cidade forte; e os poderes do sul não poderão subsistir, nem os melhores de seu povo, nem haverá força que possa subsistir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 16, 'E o que virá contra ele fará sua própria vontade, e não haverá quem possa subsistir diante dele; ele estará na terra gloriosa, e o poder de destruir estará em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 17, 'Ele decidirá vir com o poder de todo seu reino; e os corretos com ele, e [assim] fará; e lhe dará uma filha de mulheres para destruir [o reino] ; mas ela não terá sucesso, nem será para proveito dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 18, 'Depois virará seu rosto para as terras costeiras, e tomará muitas; mas um príncipe fará cessar sua humilhação por ele, e ainda fará tornar sobre ele sua humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 19, 'Então virará seu rosto para as fortalezas de sua terra; mas tropeçará e cairá, e não será mais achado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 20, 'E em seu lugar se levantará um que fará passar um cobrador de impostos para glória real; mas em poucos dias será quebrantado, não por causa de ira nem de batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 21, 'Depois se levantará em seu lugar um ser desprezível, ao qual não darão a honra real; mas virá durante a quietude, e tomará o reino por meio de enganos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 22, 'E exércitos em grande volume serão repelidos diante dele, e serão quebrantados; assim como também o príncipe do pacto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 23, 'E depois de fizerem acordos com ele, ele usará engano, e subirá; será fortalecido [mesmo] com pouca gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 24, 'Quando houver tranquilidade nas mais prósperas [regiões] da província, ele virá e fará o que nunca fizeram seus pais, nem os pais de seus pais; ele repartirá presa, despojos, e riquezas entre os seus; e voltará seus pensamentos contra as fortalezas; porém [somente] por um tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 25, 'E despertará sua forças e sua coragem contra o rei do sul, com grande exército; e o rei do sul se agitará para a guerra com grande e muito poderoso exército; mas não prevalecerá, porque tramarão planos contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 26, 'Até os que comerem de sua comida o destruirão; e seu exército será repelido, e muitos cairão mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 27, 'E o coração destes dois reis será para fazer mal, e em uma mesma mesa falarão mentiras; mas isto não terá sucesso, pois ainda [haverá] o fim no tempo determinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 28, 'E voltará para sua terra com grande riqueza, e seu coração será contra o pacto santo; e ele fará [o que decidir] , e voltará a sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 29, 'A certo tempo voltará a vir ao sul; mas a última [vinda] não será como a primeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 30, 'Porque navios de Quitim virão contra ele, de modo que ele se entristecerá, voltará, e se indignará contra o pacto santo, e ele fará [o que decidir] ; pois quando voltar, ele dará atenção aos que tiverem abandonado o pacto santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 31, 'E tropas virão da parte dele, e profanarão o santuário e a fortaleza; tirarão o contínuo [sacrifício] , e porão uma abominação assoladora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 32, 'E com lisonjas ele perverterá aos violadores do pacto; mas o povo que conhece a seu Deus com força resistirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 33, 'E os entendidos do povo ensinarão a muitos; porém cairão à espada e a fogo, por meio de cativeiro e de despojo, por [muitos] dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 34, 'E quando eles caírem, serão ajudados por um pequeno socorro; contudo muitos se aliarão a eles através de enganos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 35, 'E alguns dos sábios cairão para serem refinados, purificados e limpos, até o tempo do fim; porque [isto] ainda será para o tempo determinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 36, 'E o rei fará a sua vontade; e se exaltará, e se engrandecerá sobre todo deus; ele falará coisas arrogantes contra o Deus dos deuses, e será próspero, até que a ira se complete; pois o que está determinado será feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 37, 'Ele não respeitará os deuses de seus pais, nem para o preferido das mulheres; nem respeitará deus algum, pois se engrandecerá sobre todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 38, 'Mas em seu lugar honrará ao deus das fortalezas, um deus que seus pais nem sequer conheceram; ele o horará com ouro, prata, pedras preciosas, e com coisas de grande valor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 39, 'E ele atacará fortes fortalezas com o deus estrangeiro; aos que o reconhecerem, ele aumentará a honra; e ele os fará terem domínio sobre muitos, e repartirá a terra por preço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 40, 'E no tempo do fim o rei do sul lutará contra ele; e o rei do norte levantará como tempestade contra ele, com carruagens, cavaleiros, e muitos navios; e entrará pelas terras, arruinará como se fosse inundação, e passará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 41, 'E virá à terra gloriosa, e muitos [povos] cairão; mas estes escaparão de sua mão: Edom, Moabe, e os líderes dos filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 42, 'E estenderá sua mão a [outras] terras, e a terra do Egito não escapará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 43, 'E se apoderará dos tesouros de ouro e prata, e de todas as coisas valiosas do Egito, os líbios e os cuxitas o seguirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 44, 'Porém notícias do oriente e do norte o espantarão; e ele sairá com grande furor para destruir e matar muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 11, 45, 'E armará a tendas de seu palácio entre os mares, no glorioso monte santo; mas ele virá a seu fim, e não haverá quem o ajude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 1, 'E naquele tempo se levantará Miguel, o grande príncipe que está a favor dos filhos de teu povo; e será tempo de angústia tal que nunca houve desde que as nações surgiram até aquele tempo; mas naquele tempo o teu povo será livrado, todo aquele os que se achar escrito no livro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 2, 'E muitos dos que dormem no pó da terra ressuscitarão, uns para a vida eterna, e outros para a vergonha e o desprezo eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 3, 'E os sábios brilharão como o resplendor do céu; e os que conduzem muitos à justiça [brilharão] como as estrelas, para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 4, 'Porém tu, Daniel, guarda em segredo estas palavras e sela o livro até o tempo do fim; muitos correrão de um lado para o outro, e o conhecimento se multiplicará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 5, 'Então eu, Daniel, olhei, e eis outros dois que estavam de pé, um à margem do rio, e o outro à outra margem do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 6, 'E ele disse ao homem vestido de linho, que estava sobre as águas do rio: Quando será o fim destas maravilhas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 7, 'E ouvi o homem vestido de linho, que estava sobre as águas do rio, e levantou sua mão direita e sua esquerda ao céu, e jurou por aquele que vive eternamente; que será depois de um tempo, tempos, e a metade [de um tempo] . Quando acabarem de despedaçar o poder do povo santo, todas estas coisas serão cumpridas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 8, 'E eu ouvi, mas não entendi. Por isso eu disse: Meu senhor, o que será o cumprimento destas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 9, 'E ele disse: Caminha, Daniel, pois estas palavras estão guardadas em segredo e seladas até o tempo do fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 10, 'Muitos serão purificados, limpos, e refinados; porém os maus agirão malignamente, e nenhum dos maus entenderá, porém os sábios entenderão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 11, 'E desde o tempo em que o contínuo [sacrifício] for tirado, e posta a abominação assoladora, haverá mil duzentos e noventa dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 12, 'Bem-aventurado o que esperar, e chegar até mil trezentos e trinta e cinco dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 12, 13, 'Tu, porém, caminha até o fim; porque repousarás, e ressuscitarás em tua herança no fim dos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 1, 'A palavra do SENHOR que veio a Oseias, filho de Beeri, nos dias de Uzias, Jotão, Acaz, e Ezequias, reis de Judá, e nos dias de Joeroboão, filho de Joás, rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 2, 'O princípio da palavra do SENHOR por Oseias.Disse, pois, o SENHOR a Oseias: Vai, toma para ti uma mulher de prostituição, e filhos de prostituições; porque a terra se prostitui munto, afastando-se do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 3, 'Então ele foi, e tomou a Gômer, filha de Diblaim, a qual concebeu, e lhe deu à luz um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 4, 'E o SENHOR lhe disse: Chama o nome dele de Jezreel; porque daqui a pouco farei punição pelo sangue de Jezreel sobre a casa de Jeú, e farei cessar o reino da casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 5, 'E será que naquele dia quebrarei o arco de Israel no vale de Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 6, 'E ela voltou a conceber, e deu à luz uma filha. Então [o SENHOR] lhe disse: Chama o nome dela de Não-Amada, porque não mais amarei a casa de Israel para os perdoar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 7, 'Mas a casa de Judá amarei, e os salvarei pelo SENHOR seu Deus; e não os salvarei por arco, nem por espada, nem por batalha, nem por cavalos, nem por cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 8, 'E depois de haver desmamado a Não-Amada, ela concebeu e deu à luz um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 9, 'E [o SENHOR] disse: Chama o nome dele de Não-Meu-Povo; porque vós não sois meu povo, por isso eu não serei vosso [Deus] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 10, 'Todavia o número dos filhos de Israel será como a areia do mar, que não se pode medir nem contar. E acontecerá que, onde foi-lhes dito: Vós não sois meu povo, lhes será dito: Vós sois filhos do Deus vivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 1, 11, 'E os filhos de Judá e de Israel serão reunidos em um, e levantarão para si uma única cabeça, e subirão da terra; pois o dia de Jezreel será grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 1, 'Dizei a vossos irmãos: Meu Povo, e vossas irmãs: Amada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 2, 'Repreendei vossa mãe, repreendei; porque ela não é minha mulher, nem eu seu marido; que tire suas prostituições diante de si, e seus adultérios dentre seus peitos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 3, 'Para não acontecer que eu a deixe nua, e a ponha como no dia em que nasceu, e a faça como um deserto, e a deixe como terra seca, e a mate de sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 4, 'E não terei compaixão de seus filhos, porque são filhos de prostituições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 5, 'Pois sua mãe se prostituiu; a que os concebeu age de forma vergonhosa; porque disse: Irei atrás meus amantes, que dão meu pão e minha água, minha lã e meu linho, meu azeite e minha bebida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 6, 'Portanto eis que cercarei teu caminho com espinhos, e levantarei uma parede de sebe, de modo que ela não poderá achar suas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 7, 'E ela correrá atrás de seus amantes, mas não os alcançará; ela os buscará, mas não os achará. Então dirá: Irei, e me voltarei ao meu primeiro marido; porque era melhor para mim então do que agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 8, 'E ela não reconhecia que era eu que lhe dava o trigo, o vinho, e o azeite, e lhe multiplicava a prata e o ouro que usavam para Baal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 9, 'Portanto tomarei de volta meu trigo a seu tempo, e meu vinho à sua estação, e tirarei minha lã e meu linho que servia para cobrir sua nudez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 10, 'E agora deixarei exposta sua loucura diante dos olhos de seus amantes, e ninguém a livrará de minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 11, 'E farei cessar toda a sua alegria, suas festas, suas novas luas e seus sábados, e todas as suas festividades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 12, 'Devastarei suas vides e suas figueiras, das quais diz: Estas são meu salário, que meus amantes me deram. Eu as reduzirei a uma matagal, e os animais do campo as comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 13, 'Eu a castigarei pelos dias em que ela queimava incensos a Baal, e se adornava de seus pendentes e de suas joias, e seguia seus amantes, tendo se esquecido de mim, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 14, 'Portanto, eis que eu a atrairei, e a levarei ao deserto, e falarei ao seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 15, 'E dali lhe darei suas vinhas, e o vale de Acor por porta de esperança; e ali ela cantará como nos tempos de sua juventude, como no dia em que subiu da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 16, 'E será naquele dia, diz o SENHOR, me chamarás de meu marido, e não mais me chamarás de meu Baal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 17, 'Porque tirarei de sua boca os nomes dos baalins, e nunca mais serão lembrados por seus nomes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 18, 'E naquele dia farei por eles uma aliança com os animais do campo, as aves do céu, e os répteis da terra; e quebrarei o arco, a espada, e a batalha da terra, e os farei deitar em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 19, 'E te farei minha esposa para sempre; eu te farei minha esposa em justiça, juízo, bondade e misericórdias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 20, 'E te farei minha esposa em fidelidade, e tu conhecerás ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 21, 'E será que naquele tempo responderei,diz o SENHOR, eu responderei ao céu, e ele responderá à terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 22, 'E a terra responderá ao trigo, ao vinho, e ao azeite; e eles responderão a Jezreel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 2, 23, 'E eu a semearei para mim na terra; amarei a Não-Amada; e direi a Não-Meu-Povo: Tu és meu povo; e ele dirá: [Tu és] meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 3, 1, 'E disse-me o SENHOR: Vai, ama a mulher amada por [seu] companheiro, apesar de ser adúltera, assim como SENHOR ama os filhos de Israel, que dão atenção a outros deuses, e amam os bolos de uvas [dedicados aos ídolos] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 3, 2, 'Então eu a comprei para mim por quinze peças de prata, e um ômer e meio de cevada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 3, 3, 'E disse a ela: Tu viverás comigo por muitos dias; não te prostituirás, nem serás de outro homem; nem e eu [esperarei] por ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 3, 4, 'Porque os filhos de Israel viverão muitos dias sem rei e sem príncipe; sem sacrifício e sem estátua; sem éfode e sem ídolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 3, 5, 'Depois os filhos de Israel voltarão e buscarão ao SENHOR seu Deus, e a Davi seu rei; e temendo virão ao SENHOR e à sua bondade no fim dos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 1, 'Ouvi a palavra do SENHOR, ó filhos de Israel; porque o SENHOR briga com os moradores da terra; porque não há fidelidade, nem misericórdia, nem conhecimento de Deus na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 2, 'Perjúrio, mentira, matança, roubo e adultério prevalecem; derramamentos de sangue se acumulam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 3, 'Por isso a terra lamentará, e qualquer um que morar nela desfalecerá, com os animais do campo e as aves do céu; e até os peixes do mar morrerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 4, 'Porém ninguém brigue nem repreenda a alguém, porque teu povo é como os que brigam com o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 5, 'Por isso cairás de dia, e o profeta cairá contigo de noite; e destruirei tua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 6, 'Meu povo é destruído por falta de conhecimento. Porque tu rejeitaste o conhecimento, eu também te rejeitei do meu sacerdócio; e visto que te esqueceste a lei de teu Deus, também eu me esquecerei de teus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 7, 'Quanto mais eles se multiplicaram, mais pecaram contra mim; tornarei sua honra em vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 8, '[Os sacerdotes] comem do pecado de meu povo, e desejam a maldade das pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 9, 'Portanto tal como o povo, assim será com o sacerdote; e punirei contra ele seus caminhos, e lhe retribuirei conforme seus atos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 10, 'E comerão, mas não se fartarão; eles se prostituirão, mas não se multiplicarão, porque abandonaram ao SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 11, 'Para buscarem a prostituição, o vinho, e o mosto, que tiram o entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 12, 'Meu povo consulta a seu pedaço de madeira, e seu bastão lhes dá resposta, porque o espírito de prostituições o engana, para se prostituírem contra o Deus deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 13, 'Sobre os topos dos montes sacrificam, e queimam incenso sobre os morros, debaixo de carvalhos, álamos, e olmeiros que tenham boa sombra; por isso vossas filhas se prostituem, e vossas noras cometem adultério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 14, 'Eu não punirei vossas filhas que se prostituem, nem vossas noras que cometem adultério; porque os próprios homens se juntam com as mulheres promíscuas, e fazem sacrifícios com as prostitutas de ritos idólatras; de fato, o povo sem entendimento se arruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 15, 'Se tu, Israel, queres te prostituir, [ao menos] não faças Judá culpado. Não venhais a Gilgal, nem subais a Bete-Áven; nem jureis: Vive o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 16, 'Porque Israel se rebelou como bezerra teimosa; agora o SENHOR os apascentará como a um cordeiro num campo extenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 17, 'Efraim se associou a ídolos; deixa-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 18, 'Quando sua bebida se acaba, eles se voltam à prostituição; seus líderes amam a vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 4, 19, 'Um vento os atou em suas asas, e se envergonharão por causa de seus sacrifícios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 1, 'Ouvi isto, ó sacerdotes, prestai atenção, ó casa de Israel; escutai, ó casa do rei; porque contra vós é este julgamento; pois tendes sido um laço em Mispá, e uma rede estendida sobre Tabor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 2, 'Os rebeldes têm se aprofundado na matança, mas eu repreenderei a todos eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 3, 'Eu conheço a Efraim, e Israel não está oculto para mim; pois agora, ó Efraim, te prostituis, [e] Israel está contaminado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 4, 'Seus atos não lhe permitem se converterem a seu Deus, porque o espírito de prostituições está no meio deles, e não conhecem ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 5, 'E a soberba de Israel dará testemunho contra ele. Israel e Efraim cairão em sua maldade, e Judá cairá juntamente com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 6, 'Com suas ovelhas e com suas vacas irão buscar o SENHOR, mas não o encontrarão; ele se retirou deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 7, 'Agiram traiçoeiramente contra o SENHOR, porque geraram filhos estrangeiros; agora a lua nova os consumirá com suas propriedades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 8, 'Tocai a corneta em Gibeá, a trombeta em Ramá; gritai em Bete-Áven; atrás de ti, ó Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 9, 'Efraim será desolado no dia do castigo; nas tribos de Israel eu fiz saber o que certamente [acontecerá] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 10, 'Os príncipes de Judá são como os mudam os limites; derramarei como água meu furor sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 11, 'Efraim é oprimido, e quebrantado no julgamento, porque quis seguir regras inúteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 12, 'Por isso eu serei como traça a Efraim, e como podridão à casa de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 13, 'Quando Efraim viu sua enfermidade, e Judá a sua ferida, então Efraim subiu à Assíria, e procurou o grande rei; porém ele não poderá vos sarar, nem curar vossa ferida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 14, 'Porque eu serei como leão a Efraim, e como leão jovem à casa de Judá; eu mesmo a despedaçarei, e irei embora; eu a levarei, e não haverá quem a livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 5, 15, 'Irei, [e] voltarei a meu lugar, até que se reconheçam culpados, e busquem minha face. Em sua angústia, eles me buscarão ansiosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 1, 'Vinde, e voltemo-nos ao SENHOR; porque ele despedaçou, mas nos curará; ele feriu, mas nos porá curativo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 2, 'Depois de dois dias ele nos dará vida; ao terceiro dia nos ressuscitará, e diante dele viveremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 3, 'Conheçamos, e prossigamos em conhecer ao SENHOR; sua vinda está preparada como o nascer do sol; ele virá a nós como a chuva, como a chuva da primavera, que rega a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 4, 'Que farei a ti, ó Efraim? Que farei a ti, ó Judá? Vossa bondade é como a neblina da manhã, como o orvalho da madrugada, que logo desaparece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 5, 'Por isso eu os cortei com os profetas; pelas palavras de minha boca os matei; e teus juízos sairão como a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 6, 'Pois eu quero misericórdia, e não sacrifício; e conhecimento de Deus mais do que holocaustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 7, 'Porém eles, assim como Adão, transgrediram o pacto; ali agiram traiçoeiramente contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 8, 'Gileade é a cidade dos que praticam a injustiça; manchada está de sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 9, 'Tal como um bando de assaltantes à espera de um homem, assim é o grupo de sacerdotes; matam no caminho para Siquém; eles praticam abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 10, 'Na casa de Israel tenho visto coisa detestável; ali Efraim se prostitui, Israel se contamina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 6, 11, 'Também para ti, ó Judá, há uma ceifa, quando eu restaurar o meu povo de seu infortúnio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 1, 'Ainda que eu esteja [disposto] a curar Israel, expostas estão a perversidade de Efraim e as maldades de Samaria, porque praticam a falsidade; o ladrão vem, e o bando de assaltantes despoja do lado de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 2, 'E nem percebem em seus corações eu me lembro de toda a maldade deles; agora seus atos os cercam; diante de mim estão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 3, 'Com sua maldade alegram ao rei, e com suas mentiras aos príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 4, 'Todos eles cometem adultério; semelhantes são ao forno aceso pelo padeiro, que deixa de atiçar depois da massa estar feita, até que esteja levedada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 5, 'No dia do nosso rei, os príncipes ficam doentes pelo calor do vinho; ele estende sua mão com os zombadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 6, 'Porque preparam seus corações para suas ciladas como a um forno; toda a noite seu padeiro dorme, pela manhã arde como fogo flamejante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 7, 'Todos eles se aquecem como um forno, e devoraram os seus juízes; todos os seus reis caem; ninguém há entre eles que clame a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 8, 'Efraim se mistura com os povos; Efraim é um bolo que não foi virado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 9, 'Estrangeiros devoram sua riqueza, sem que ele perceba; e até o cabelo grisalho se espalha por ele, e ele não percebeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 10, 'A soberba de Israel dá testemunho contra ele, porém não se convertem ao SENHOR seu Deus, nem o buscam, apesar de tudo isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 11, 'E foi Efraim como pomba imprudente, sem inteligência; chamam ao Egito, vão à Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 12, 'Quando forem, estenderei minha rede sobre eles; eu os farei cair como as aves do céu. Eu os castigarei conforme o que se tem ouvido quando eles se reúnem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 13, 'Ai deles, porque se afastaram de mim; destruição sobre eles, porque se rebelaram contra mim; eu os livraria, porém falam mentiras contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 14, 'E não clamam a mim com seus corações quando gemem sobre suas camas; eles se reúnem para o trigo e o vinho, [porém] de mim se afastam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 15, 'Eu os treinei, [e] fortalecei seus braços, porém pensam o mal contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 7, 16, 'Eles se voltam, [mas] não para o Altíssimo. Eles são como um arco defeituoso; seus príncipes caem à espada por causa da insolência de suas línguas; por isso serão escarnecidos na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 1, '[Põe] a trombeta em tua boca. [O inimigo vem] como uma águia contra a casa do SENHOR, porque violaram meu pacto, e transgrediram minha lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 2, '[Então] clamarão a mim: Deus meu, nós, Israel, te conhecemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 3, 'Israel rejeitou o bem; o inimigo o perseguirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 4, 'Eles fizeram reis, mas não de mim; constituíram príncipes, porém sem que eu soubesse; de sua prata e de seu ouro fizeram ídolos para si, para que sejam exterminados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 5, 'O teu bezerro foi rejeitado, ó Samaria; minha ira está acesa contra eles; até quando não suportarão a pureza?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 6, 'Porque isso procede de Israel, um artífice o fez; isso não é Deus; por isso o bezerro de Samaria será desfeito em pedaços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 7, 'Porque semearam vento, colherão tempestade; não haverá colheita, nem a produção dará farinha; mesmo se a der, estrangeiros a tragarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 8, 'Israel é tragado; agora são como um vaso que ninguém dá valor entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 9, 'Porque eles subiram à Assíria, [como] um jumento selvagem solitário; Efraim se vendeu aos amantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 10, 'Ainda que tenham se vendido às nações, agora eu as ajuntarei; e começarão a ser reduzidos pela opressão do rei de príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 11, 'Porque Efraim multiplicou os altares para pecar, os altares feitos para cometer pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 12, 'Eu lhe escrevi as grandezas de minha lei, mas foram consideradas coisa estranha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 13, 'Quanto aos sacrifícios de ofertas a mim, eles sacrificam a carne, e a comem; porém o SENHOR não os aceita. Agora ele se lembrará de sua perversidade, e punirá seus pecados; eles voltarão ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 8, 14, 'Porque Israel se esqueceu de seu Criador, e edificou templos; Judá multiplicou cidades fortificadas; porém mandarei fogo em suas cidades, que consumirá seus palácios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 1, 'Não te alegres tanto, ó Israel, como os [outros] povos, pois tu te prostituis, afastando-te de teu Deus; tu amas o salário de prostituta em todas as eiras de trigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 2, 'A eira e a prensa de uvas não os manterão; e o vinho novo lhes faltará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 3, 'Não permanecerão na terra do SENHOR; em vez disso, Efraim voltará ao Egito, e na Assíria comerão coisa imunda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 4, 'Não derramarão ofertas de bebida ao SENHOR, nem seus sacrifícios lhe serão agradáveis; [seu pão] será para eles como pão de lamento; todos os que comerem dele, serão imundos; porque o pão deles será para saciar sua própria fome, e não virá para a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 5, 'Que fareis no dia solene, no dia festa do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 6, 'Porque eis que eles vão embora por causa da destruição; o Egito os recolherá, Mênfis os sepultará; urtigas herdarão sua prata, espinhos [crescerão] em suas tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 7, 'Chegaram os dias da punição, chegaram os dias da retribuição; os israelitas saberão; o profeta é [considerado] louco, o homem espiritual [é visto como] tolo, por causa da grandeza de tua maldade e do grande ódio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 8, 'O profeta é um guarda de Efraim para meu Deus; [mas para ele há] laços de caçador em todos os seus caminhos, e ódio na casa de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 9, 'Corromperam-se profundamente, como nos dias de Gibeá: [Deus] se lembrará de suas perversidades, seus pecados punirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 10, 'Eu achei a Israel como uvas no deserto; eu vi a vossos pais como a primeira fruta da figueira em seu princípio. [Porém] eles foram a Baal-Peor, dedicaram-se a esta vergonha, e se tornaram tão abomináveis quanto aquilo que amaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 11, 'A glória de Efraim voará como ave; não haverá nascimento, nem gravidez, nem concepção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 12, 'Ainda que venham a criar seus filhos, contudo eu os privarei deles, de modo que reste nenhum. Ai deles quando deles eu me afastar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 13, 'Vi que Efraim era como Tiro, plantada num lugar agradável; mas Efraim trará seus filhos ao matador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 14, 'Dá-lhes, SENHOR, o que lhes darás? Dá-lhes ventre que aborte, e seios sem leite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 15, 'Por causa de toda a sua malícia em Gilgal, ali eu os odiei; por causa da malícia de suas obras eu os expulsarei de minha casa; eu não mais os amarei; todos os seus príncipes são rebeldes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 16, 'Efraim foi ferido, sua raiz se secou, não darão fruto; e que ainda que gerem, eu matarei os desejáveis [frutos] de seu ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 9, 17, 'Meu Deus os rejeitará porque não o ouviram; e andarão sem rumo entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 1, 'Israel era uma vinha fértil, que dava frutos para si mesma; quanto mais se multiplicavam seus frutos, mais multiplicou altares, quanto mais a sua terra prosperava, mais adornaram suas colunas pagãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 2, 'O coração deles está dividido, agora serão culpados; ele quebrará seus altares e destruirá suas colunas pagãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 3, 'Pois dirão agora: Não temos rei porque não tivemos temor ao SENHOR; mas o que um rei faria por nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 4, 'Falaram palavras jurando falsamente ao fazerem pactos; por isso que a disputa judicial brota como erva venenosa nos sulcos dos campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 5, 'Os moradores de Samaria estarão atemorizados por causa do bezerro Bete-Áven; pois seu povo por causa dele lamentará, e seus sacerdotes, que nele se alegravam, [lamentarão] por sua glória, que se foi dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 6, 'Além disso, ele será levado à Assíria como presente ao grande rei; Efraim receberá vergonha, Israel será envergonhado por causa de seu conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 7, 'O rei de Samaria será eliminado como um graveto sobre a superfície das águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 8, 'E os altos cultuais de Áven, o pecado de Israel, serão destruídos; espinhos e cardos crescerão sobre seus altares. E dirão aos montes: Cobri-nos; e aos morros: Caí sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 9, 'Desde os dias de Gibeá tu tens cometido pecado, ó Israel; ali continuaram; por acaso a guerra em Gibeá não alcançou os filhos da perversidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 10, 'Quando eu quiser, eu os castigarei; e povos se reunirão contra eles, para que sejam presos por causa de sua dupla transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 11, 'Efraim é uma bezerra domada, que amava trilhar; mas eu porei [um jugo] sobre seu belo pescoço; farei com que Efraim seja montado; Judá lavrará, Jacó fará sulcos na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 12, 'Semeai para vós justiça, colhei para vós bondade; lavrai para vós lavoura; porque é o tempo de buscar ao SENHOR, até que ele venha, e faça chover justiça sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 13, 'Lavrastes maldade, colhestes perversidade; comestes o fruto de mentira; porque confiaste em teu caminho, na multidão de teus guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 14, 'Portanto entre teu povo se levantará tumulto, e todas as tuas fortalezas serão destruídas, assim como Salmã destruiu a Bete-Arbel no dia da batalha; ali a mãe foram despedaçada com [seus] filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 10, 15, 'Assim Betel fará convosco, por causa de vossa grande malícia; ao amanhecer o rei de Israel será exterminado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 1, 'Quando Israel era menino, eu o amei, e do Egito chamei a meu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 2, 'Quanto mais os chamavam, mais eles se afastavam de sua presença; sacrificavam aos Baalins, e ofereciam incenso às imagens de escultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 3, 'Eu, todavia, ensinei Efraim a andar, tomando-os pelos seus braços; porém não reconheceram que eu os curava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 4, 'Com cordas humanas eu os puxei, com cordas de amor; e fui para eles como os que levantam o jugo de sobre suas cabeças, e lhes dei alimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 5, '[Israel] não voltará à terra do Egito, mas o assírio será seu rei, porque recusam se converter.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 6, 'E a espada moverá sobre suas cidades; destruirá os ferrolhos de seus portões, e acabará com seus planos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 7, 'Porém meu povo insiste em se desviar de mim; ainda que chamem ao Altíssimo, ninguém de fato o exalta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 8, 'Como posso te abandonar, ó Efraim? Como posso te entregar, ó Israel? Como posso fazer de ti como Admá, [ou] te tornar como a Zeboim? Meu coração se comove dentro de mim, todas as minhas compaixões estão acesas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 9, 'Não executarei o furor de minha ira, não voltarei a destruir Efraim; porque eu sou Deus, e não homem, o Santo no meio de ti; e não entrarei na cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 10, 'Ao SENHOR seguirão; ele rugirá como leão; quando ele rugir os filhos virão tremendo desde o ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 11, 'Tremendo virão do Egito como um pássaro, e da terra da Assíria como uma pomba; e eu os farei habitar em suas casas, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 11, 12, 'Efraim me cercou com mentira, e a casa de Israel com engano; mas Judá ainda andava com Deus, e era é fiel ao Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 1, 'Efraim se alimenta de vento, e persegue o vento oriental o dia todo; multiplica a mentira e a destruição; e fazem aliança com a Assíria, e azeite se leva ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 2, 'O SENHOR também tem uma briga judicial com Judá, e punirá Jacó conforme seus caminhos; ele lhe retribuirá conforme seus atos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 3, 'No ventre [da mãe] pegou pelo calcanhar de seu irmão, e em sua força lutou com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 4, 'Lutou com o anjo, e prevaleceu; chorou, e lhe suplicou; [em] Betel o achou, e ali falou conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 5, 'O próprio SENHOR, Deus dos exércitos; o SENHOR é seu memorial.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 6, 'Tu pois, converte-te a teu Deus; guarda tu a misericórdia e a justiça, e espera em teu Deus continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 7, 'O mercador tem balança enganosa em sua mão, pois ama oprimir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 8, 'E Efraim diz: Certamente eu sou rico; tenho obtido para mim muitos bens; [em] todo o meu trabalho ninguém pode achar em mim perversidade que seja pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 9, 'Porém eu sou o SENHOR teu Deus, desde a terra do Egito; eu ainda te farei morar em tendas, como nos dias solenes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 10, 'E falei aos profetas, e eu multipliquei a visão profética; e por meio dos profetas propus parábolas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 11, 'Visto que Gileade é injusta, certamente [seus moradores] são inúteis. Em Gilgal sacrificam bois, e até seus altares são como amontoados [de pedras] nos sulcos dos campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 12, 'Mas Jacó fugiu à terra de Arã, e Israel serviu em troca de uma mulher, e por uma mulher apascentou [ovelhas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 13, 'Mas o SENHOR por um profeta fez subir a Israel do Egito, e por um profeta foi preservado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 12, 14, '[Porém] Efraim o ofendeu amargamente; por isso deixará [a culpa de] seus sangues sobre ele, e seu Senhor lhe retribuirá sua desonra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 1, 'Quando Efraim falava, havia tremor; ele era exaltado em Israel; mas se tornou culpado por causa de Baal, e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 2, 'Agora pecam cada vez mais, e de sua prata fizeram para si uma imagem de fundição, ídolos segundo seu entendimento, todos eles obra de artesãos; acerca dos quais dizem: As pessoas que sacrificam beijam bezerros!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 3, 'Por isso serão como a névoa da manhã, como o orvalho da madrugada que passa; como a palha que o vento leva da eira, e como a fumaça que sai da chaminé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 4, 'Porém eu sou o SENHOR teu Deus, desde a terra do Egito; portanto não conhecerás a Deus algum a não ser a mim, porque não há Salvador além de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 5, 'Eu te conheci no deserto, na terra seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 6, 'Depois se fartaram em seus pastos; quando ficaram fartos, seus corações se exaltaram; por isso se esqueceram de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 7, 'Por isso eu serei para eles como leão; como leopardo os espiarei no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 8, 'Como ursa de quem tomaram os filhotes os encontrarei, e rasgareis os peitorais de seu coração; e ali os devorarei como leão; os animais do campo os despedaçarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 9, 'Estás perdido, ó Israel, porque é em mim que está tua ajuda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 10, 'Onde está agora o teu rei, para que te proteja em todas as tuas cidades? E teus juízes, dos quais disseste: Dá-me um rei e príncipes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 11, 'Eu te dei um rei em minha ira, e [o] tirei em meu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 12, 'A maldade de Efraim está registrada; seu pecado está guardado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 13, 'Dores de parto lhe virão; ele é um filho insensato, pois não deveria permanecer dentro na hora do parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 14, 'Eu os resgatarei do poder do Xeol e os livrarei da morte. Onde estão, Ó morte, tuas pestilências? Onde está, ó Xeol, tua perdição? A compaixão será escondida de meus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 15, 'Ainda que ele frutifique entre os irmãos, virá o vento oriental, vento do SENHOR, subindo do deserto, e sua fonte se secará, sua nascente se secará; ele saqueará o tesouro de tudo o que for precioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 13, 16, 'Samaria levará sua culpa, porque se rebelou contra o seu Deus. Cairão a espada; suas crianças serão despedaçadas, e suas grávidas terão seus ventres abertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 1, 'Converte-te, ó Israel, ao SENHOR teu Deus; pois caíste por tua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 2, 'Tomai convosco palavras, e convertei-vos ao SENHOR; dizei-lhe: Tira toda a maldade, e aceita o que é bom; então ofereceremos nossos lábios como bezerros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 3, 'Os assírios não nos salvarão; não cavalgaremos sobre cavalos, e nunca mais chamaremos à obra de nossas mãos de nossos deuses; porque em ti o órfão alcançará misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 4, 'Eu curarei sua rebelião, eu os amarei voluntariamente, porque minha ira terá se afastado deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 5, 'Eu serei a Israel como o orvalho; ele florescerá como lírio, e estenderá suas raízes como o [cedro do] Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 6, 'Seus ramos se estenderão; sua beleza como a da oliveira, e sua fragrância como o [cedro do] Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 7, 'Voltarão, e habitarão abaixo de sua sombra: serão vivificados [como] o trigo, e florescerão como a videira; sua fama será como o vinho do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 8, 'Ó Efraim, o que mais eu tenho a ver com os ídolos? Eu o responderei, e dele cuidarei; serei a ele como a faia verde; de mim vem o teu fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 28, 'Oséias', 'Os', 14, 9, 'Quem é sábio entenda estas coisas, e o prudente as reconheça; porque os caminhos do SENHOR são retos, e os justos andarão neles; mas os transgressores neles cairão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 1, 'Palavra do SENHOR que veio a Joel, filho de Petuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 2, 'Ouvi isto, anciãos, e escutai, todos os moradores desta terra. Por acaso isto aconteceu em vossos dias, ou nos dias dos vossos pais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 3, 'Contai disso aos vossos filhos, e vossos filhos aos seus filhos, e seus filhos à outra geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 4, 'O que restou do gafanhoto cortador o gafanhoto comedor comeu; e o que restou do gafanhoto comedor o gafanhoto devorador comeu, e o que restou do gafanhoto devorador o gafanhoto destruidor comeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 5, 'Despertai, vós bêbados, e chorai; gemei todos vós que bebeis vinho, por causa do suco de uva, porque foi tirado de vossa boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 6, 'Porque uma nação subiu sobre minha terra, poderosa e sem número; seus dentes são dentes de leão, e têm presas de leoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 7, 'Assolou minha videira, e devastou minha figueira; desnudou-a por completo e a derrubou; seus ramos ficaram brancos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 8, 'Chora tu como a virgem vestida de saco por causa do marido de sua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 9, 'As ofertas de cereais e de bebidas se acabaram da casa do SENHOR; os sacerdotes, servos do SENHOR, estão de luto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 10, 'O campo foi assolado, a terra está de luto; porque o trigo foi destruído, o suco de uva se secou, o azeite está em falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 11, 'Envergonhai-vos, trabalhadores; gemei, plantadores de vinhas, pelo trigo e pela a cevada; porque a colheita do campo pereceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 12, 'A vide se secou, a figueira definhou, assim como a romeira, a palmeira, e a macieira; todas as árvores do campo se secaram; por isso a alegria se secou entre os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 13, 'Cingi-vos e lamentai, sacerdotes; gemei, ministros do altar; vinde e deitai em sacos, trabalhadores de meu Deus; porque as ofertas de alimentos e de bebidas foram tiradas da casa de vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 14, 'Santificai um jejum; convocai uma reunião solene; congregai os anciãos e todos os moradores desta terra na casa do SENHOR vosso Deus, e clamai ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 15, 'Ai daquele dia! Porque perto está o dia do SENHOR, e virá do Todo-Poderoso como destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 16, 'Por acaso não foi tirado o alimento de diante de nossos olhos, a alegria e o prazer da casa de nosso Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 17, 'As sementes se apodreceram debaixo de seus torrões, os celeiros foram assolados, os depósitos foram derrubados; porque o trigo se secou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 18, 'Como geme o gado! As manadas dos vacas estão confusas, porque não têm pasto! Os rebanhos das ovelhas estão desolados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 19, 'A ti, ó SENHOR, eu clamo; porque o fogo consumiu os pastos do deserto, e chama incendiou todas as árvores do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 1, 20, 'Até os animais do campo clamam a ti, porque os rios de águas se secaram, e o fogo consumiu os pastos do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 1, 'Tocai a trombeta em Sião, e alertai em alta voz no meu santo monte; perturbem-se todos os moradores desta terra; porque o dia do SENHOR vem, porque perto está.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 2, 'Dia de trevas e de escuridão, dia de nuvens e densas trevas, como a madrugada espalhada sobre os montes; um povo grande e poderoso, como nunca houve desde a antiguidade, nem depois dele jamais haverá, de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 3, 'Diante dele o fogo consome, e atrás dele a chama arde; a terra adiante dele é como o jardim do Éden, mas atrás dele como deserto devastado; nada há que dele possa escapar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 4, 'Sua aparência é como a aparência de cavalos, e correrão como cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 5, 'Saltarão como estrondo de carruagens sobre as topos dos montes, como som de chama de fogo que consome a palha, como povo poderoso, em posição de combate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 6, 'Diante dele os povos se angustiarão, todos os rostos se afligirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 7, 'Como guerreiros correrão, como homens de guerra subirão a muralha; e cada um irá em seus caminhos, e não torcerão suas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 8, 'Nenhum apertará ao outro; irão cada um em seu percurso; irrompem sem desfazerem suas fileiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 9, 'Irão pela cidade, correrão pela muralha, subirão nas casas, entrarão pelas janelas como ladrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 10, 'A terra se abala diante deles, o céu se estremece; o sol e a lua se escurecem, e as estrelas retiram seu brilho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 11, 'E o SENHOR levanta sua voz diante de seu exército; porque suas tropas são muito grandes; porque forte é aquele que cumpre sua palavra; porque o dia do SENHOR é grande, e muito terrível; quem poderá o suportar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 12, 'Por isso agora o SENHOR diz: Convertei-vos a mim com todo o vosso coração, com jejum, choro e pranto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 13, 'Rasgai vosso coração, e não vossas vestes.Convertei-vos ao SENHOR vosso Deus, porque ele é piedoso e misericordioso, que demora para se irar, e é grande em bondade, e que se arrepende de castigar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 14, 'Quem sabe talvez ele volte atrás e se arrependa, e deixe após si uma bênção, uma oferta de alimento de de bebida ao SENHOR vosso Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 15, 'Tocai a trombeta em Sião, santificai um jejum, convocai uma reunião solene.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 16, 'Reuni o povo, santificai a congregação, juntai os anciãos, reuni as crianças e os que mamam; saia o noivo de seu cômodo, e a noiva de seu quarto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 17, 'Os sacerdotes, trabalhadores do SENHOR, chorem entre o pórtico e o altar, e digam: Poupa a teu povo, SENHOR, e não entregues tua herança à humilhação, para que as nações a dominem. Por que entre os povos diriam: Onde está o Deus deles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 18, 'Então o SENHOR terá zelo por sua terra, e poupará a seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 19, 'E o SENHOR responderá e dirá a seu povo: Eis que eu vos envio pão, suco de uva, e azeite, e deles sereis saciados; e nunca mais vos entregarei à humilhação entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 20, 'E afastarei de vós o [exército] do norte, e o lançarei na terra seca e deserta; sua frente será para o mar oriental, e sua retaguarda para o mar ocidental, e exalará seu mau cheiro; subirá sua podridão, porque fez grandes coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 21, 'Não temas, ó terra; alegra-te e encha-te de alegria, porque o SENHOR tem feito grandes coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 22, 'Não temais, vós animais do campo; porque os pastos do deserto voltarão a ficar verdes, porque as árvores darão seu fruto, a figueira e a videira mostrarão seu vigor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 23, 'E vós, filhos de Sião, alegrai-vos e enchei-vos de alegria no SENHOR vosso Deus; porque ele vos dará a primeira chuva com justiça, e fará descer sobre vós as primeiras e últimas chuvas do ano, assim como era antes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 24, 'E as eiras se encherão de trigo, e as prensas transbordarão de suco de uva e azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 25, 'Assim vos restituirei dos anos em que comeram o cortador, o comedor, o devorador e o destruidor, o meu grande exército que enviei contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 26, 'E comereis abundantemente até vos saciar; e louvareis o nome do SENHOR vosso Deus, que fez maravilhas convosco; e nunca mais meu povo será envergonhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 27, 'E sabereis que eu estou no meio de Israel, e que eu sou o SENHOR vosso Deus, e não há outro; e meu povo nunca mais será envergonhado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 28, 'E será depois que derramarei meu Espírito sobre toda carne; e vossos filhos e vossas filhas profetizarão; vossos velhos terão sonhos, e vossos jovens terão visões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 29, 'E também sobre os servos e sobre as servas, naqueles dias derramarei o meu Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 30, 'E mostrarei maravilhas no céu e na terra; sangue, fogo, e colunas de fumaça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 31, 'O sol se tornará em trevas, e a lua em sangue, antes que venha o grande e temível dia do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 2, 32, 'E será que todo aquele que invocar o nome do SENHOR será salvo; porque no monte de Sião e em Jerusalém haverá livramento, assim como o SENHOR disse, entre os que restarem, aos quais o SENHOR chamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 1, 'Porque eis que naqueles dias e naquele tempo eu restaurarei Judá e Jerusalém de seu infortúnio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 2, 'Então ajuntarei todas as nações, e as farei descer ao vale de Josafá; e ali entrarei em juízo com elas por causa do meu povo, e de minha herança Israel, aos quais dispersaram entre as nações, e repartiram minha terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 3, 'E lançaram sortes sobre meu povo, e deram os rapazes em troca de prostitutas, e venderam as moças em troca de vinho para beberem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 4, 'Além disso, o que tendes a ver comigo vós, Tiro e Sidom, e todas as regiões da Filístia? Quereis vos vingar de mim? E se quereis vos vingar de mim, apressadamente eu vos retribuirei o pagamento sobre vossa cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 5, 'Pois levastes minha prata e meu ouro, e minhas coisas valiosas e boas pusestes em vossos templos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 6, 'E vendestes os filhos de Judá e os filhos de Jerusalém aos filhos dos gregos, para os distanciar de sua pátria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 7, 'Eis que eu os levantarei do lugar para onde os vendestes, e retribuirei vosso pagamento sobre vossa cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 8, 'E venderei vossos filhos e vossas filhas na mão dos filhos de Judá, e eles os venderão aos sabeus, uma nação distante; porque o SENHOR falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 9, 'Proclamai isto entre as nações, convocai uma guerra; despertai aos guerreiros, acheguem-se, venham todos os homens de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 10, 'Fazei espadas de vossas enxadas, e lanças de vossas foices; diga o fraco: Sou forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 11, 'Ajuntai-vos e vinde, todas as nações ao redor, e reuni-vos. (Ó SENHOR, faze vir ali os teus fortes!)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 12, 'Levantem-se as nações, e subam ao vale de Josafá; porque ali eu me sentarei para julgar todas as nações ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 13, 'Lançai a foice, porque a colheita já está madura. Vinde, descei; porque a prensa de uvas está cheia, os tanques transbordam; porque a maldade deles é grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 14, 'Multidões! Multidões no vale da decisão! Porque perto está o dia do SENHOR no vale da decisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 15, 'O sol e a lua se escurecerão, e as estrelas recolherão seu brilho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 16, 'E o SENHOR bramará desde Sião, e dará sua voz desde Jerusalém, e os céus e a terra tremerão; mas o SENHOR será o refúgio de seu povo, e a fortaleza dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 17, 'Então sabereis que eu sou o SENHOR vosso Deus, que habito em Sião, o meu santo monte; e Jerusalém será santa, e estrangeiros não mais passarão mais por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 18, 'E será naquele tempo, que os montes destilarão suco de uva, e os morros fluirão leite, e por todos os ribeiros de Judá correrão águas; e sairá uma fonte da casa do SENHOR, que regará o vale de Sitim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 19, 'O Egito será uma assolação, e Edom se tornará um deserto assolado, por causa da violência que fizeram aos filhos de Judá, em cuja terra derramaram sangue inocente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 20, 'Mas Judá permanecerá para sempre, e Jerusalém de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 29, 'Joel', 'Jl', 3, 21, 'E purificarei o sangue que não tinha purificado; e o SENHOR habitará em Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 1, 'As palavras de Amós, que estava entre os pastores de Tecoa, as quais ele viu sobre Israel nos dias de Uzias rei de Judá, e nos dias de Jeroboão, filho de Joás, rei de Israel, dois anos antes do terremoto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 2, 'E disse: O SENHOR bramará desde Sião, e dará sua voz desde Jerusalém; e as habitações dos pastores se prantearão, e o topo do Carmelo se secará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 3, 'Assim diz o SENHOR: Por três transgressões de Damasco, e pela quarta, não desviarei [seu castigo] ; porque trilharam a Gileade com trilhos de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 4, 'Por isso meterei fogo na casa de Hazael, que consumirá os palácios de Ben-Hadade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 5, 'E quebrarei o ferrolho de Damasco, e exterminarei o morador do vale de Áven, e o dono do cetro de de Bete-Éden; e o povo da Síria será levado em cativeiro a Quir, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 6, 'Assim diz o SENHOR: Por três transgressões de Gaza, e pela quarta, não desviarei [seu castigo] ; pois levaram a todos do povo em cativeiro, para os entregar a Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 7, 'Por isso meterei fogo no muro de Gaza, que consumirá seus palácios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 8, 'E exterminarei o morador de Asdode, e o dono do cetro de Asquelom; e tornarei minha mão contra Ecrom, e o resto dos filisteus perecerá, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 9, 'Assim diz o SENHOR: Por três transgressões de Tiro, e pela quarta, não desviarei [seu castigo] ; porque entregaram todo o povo em cativeiro a Edom, e não se lembraram do pacto de irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 10, 'Por isso meterei fogo no muro de Tiro, que consumirá seus palácios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 11, 'Assim diz o SENHOR: Por três transgressões de Edom, e pela quarta, não desviarei [seu castigo] ; porque perseguiu seu irmão à espada, e extinguiu suas misericórdias; e sua ira [o] despedaçou continuamente, e mantém sua indignação eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 12, 'Por isso meterei fogo em Temã, que consumirá os palácios de Bosra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 13, 'Assim diz o SENHOR: Por três transgressões dos filhos de Amom, e pelo quarta, não desviarei [seu castigo] ; porque rasgaram o ventre das grávidas de Gileade, para expandirem seus territórios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 14, 'Por isso acenderei fogo no muro de Rabá, que consumirá seus palácios com grito no dia de batalha, com tempestade no dia do vento forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 1, 15, 'E seu rei irá ao cativeiro, e junto dele seus príncipes, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 1, 'Assim diz o SENHOR: Por três transgressões de Moabe, e pela quarta, não desviarei [seu castigo] ; porque queimou os ossos do rei de Edom até os tornar em cal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 2, 'Por isso meterei fogo em Moabe, que consumirá os palácios de Queriote; e Moabe morrerá em tumulto, com grito e som de trombeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 3, 'E exterminarei o juiz do meio dele, e matarei a todos seus príncipes com ele,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 4, 'Assim diz o SENHOR: Por três transgressões de Judá, e pela quarta, não desviarei [seu castigo] ; porque rejeitaram a lei do SENHOR, e não guardaram seus estatutos; e foram enganados por suas mentiras, as quais seus pais seguiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 5, 'Por isso meterei fogo em Judá, que consumirá os palácios de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 6, 'Assim diz o SENHOR: Por três transgressões de Israel, e pela quarta, não desviarei [seu castigo] ; porque vendem o justo em troca de dinheiro, e o pobre por um par de sapatos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 7, 'Eles pisam a cabeça dos pobres no pó da terra, e distorcem o caminho dos humildes; um homem e seu pai vão a uma [mesma] moça, para profanarem o meu santo nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 8, 'E se deitam junto a qualquer altar com roupas tomadas em penhor, e bebem vinho tomado como multa da casa de seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 9, 'Eu, pelo contrário, destruí diante deles os amorreus, cuja altura era como a altura dos cedros, e eram fortes como carvalhos; e destruí seu fruto acima, e suas raízes abaixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 10, 'Também vos fiz a vós subir da terra do Egito, e por quarenta anos vos conduzi pelo deserto, para que possuísseis a terra dos amorreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 11, 'E levantei [alguns] de vossos filhos para profetas, e de vossos rapazes para que fossem nazireus. Não é isto assim, filhos de Israel?Diz o SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 12, 'Mas aos nazireus destes de beber vinho; e aos profetas mandastes, dizendo: Não profetizeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 13, 'Pois eis que eu vos esmagarei em vosso lugar, tal como uma carroça cheia de feixes esmaga;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 14, 'De modo que o veloz não conseguirá escapar, nem o forte conseguirá usar de sua força, nem o guerreiro livrará sua vida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 15, 'E o que maneja o arco não subsistirá, nem o veloz de pés se livrará, nem o que monta em cavalo livrará sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 2, 16, 'O mais corajoso entre os guerreiros fugirá nu naquele dia, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 1, 'Ouvi esta palavra que o SENHOR fala contra vós, ó filhos de Israel, contra toda família que eu fiz subir da terra do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 2, 'Somente reconheci a vós mesmos de todas as famílias da terra; por isso punirei contra vós todas as vossas injustiças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 3, 'Por acaso irão dois juntos, se não estiverem de acordo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 4, 'Rugirá o leão no bosque se não houver presa? Dará o leãozinho seu som desde sua cova, se nada tiver capturado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 5, 'Cairá o ave no laço na terra, se não houver armadilha para ela? Se levantará o laço da terra, se nada houver prendido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 6, 'Tocará a trombeta na cidade, e o povo não se estremecerá? Haverá alguma calamidade na cidade que o SENHOR não tenha feito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 7, 'Certamente o Senhor DEUS não fará coisa alguma sem ter revelado seu segredo a seus servos os profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 8, 'Quando o leão ruge, quem não temerá? Quando o Senhor DEUS fala, quem não profetizará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 9, 'Anunciai nos palácios de Asdode e nos palácios da terra do Egito, e dizei: Reuni-vos sobre os montes de Samaria, e vede os grandes tumultos no meio dela, e as opressões no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 10, 'E não sabem fazer o que é correto, diz o SENHOR; em seus palácios acumulam bens [obtidos] por violência e destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 11, 'Portanto o Senhor DEUS diz assim: Um inimigo! Ele está ao redor da terra, e derrubará de ti a tua fortaleza, e teus palácios serão saqueados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 12, 'Assim diz o SENHOR: Tal como o pastor livra da boca do leão duas pernas ou a ponta de uma orelha, assim os filhos de Israel que moram em Samaria serão livrados, com um canto da cama, e um pedaço do leito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 13, 'Ouvi e testemunhai contra a casa de Jacó, diz o SENHOR Deus dos exércitos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 14, 'Que no dia em que eu punir as transgressões de Israel sobre ele, também farei punição sobre os altares de Betel; e as pontas do altar serão cortadas, e cairão por terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 3, 15, 'E ferirei a casa do inverno com a casa do verão, e as casas de marfim se acabarão; e muitas casas terão fim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 1, 'Ouvi esta palavra, vós vacas de Basã, que estais no monte de Samaria; que oprimis os pobres, que quebrantais os necessitados, que dizeis a seus senhores: Trazei nossa bebida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 2, 'O Senhor DEUS jurou por sua santidade: Eis que vêm dias sobre vós em que vos levarão em ganchos, e a vossos descendentes em anzóis de pesca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 3, 'E saireis pelas brechas cada uma atrás da outra, e sereis lançadas para Harmom, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 4, 'Ide a Betel, e transgredi; em Gilgal aumentai as transgressões, e de manhã trazei vossos sacrifícios, vossos dízimos ao terceiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 5, 'E oferecei sacrifício de louvores com lêvedo, e anunciai ofertas voluntárias; pois é assim que quereis, ó filhos de Israel,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 6, 'Eu também vos dei bocas vazias em todas vossas cidades, e falta de pão em todos os vossos lugares, contudo não vos convertestes a mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 7, 'Além disso eu vos retive a chuva três meses antes da colheita; e fiz chover sobre uma cidade, e sobre outra cidade não fiz chover; sobre um campo choveu; mas o outro campo sobre o qual não choveu, se secou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 8, 'De modo que [os moradores de] duas ou três cidades perambulavam até uma cidade para beberem água, mas não se saciavam; contudo não vos convertestes a mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 9, 'Eu vos feri com ferrugem e doenças nas plantas; a multidão de vossos jardins e vossas vinhas, vossas figueiras e vossas oliveiras o gafanhoto comeu; contudo não vos convertestes a mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 10, 'Enviei entre vós a pestilência, à maneira do Egito; matei à espada vossos rapazes, e deixei que capturassem vossos cavalos; e fiz subir o mau cheiro de vossos exércitos até vossas narinas; contudo não vos convertestes a mim,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 11, 'Transtornei a alguns dentre vós, como quando Deus transtornou a Sodoma e a Gomorra, e fostes como tição escapado do fogo; contudo não vos convertestes a mim, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 12, 'Portanto assim farei a ti, ó Israel; e visto que te farei isto, ó Israel, prepara-te para te encontrares com teu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 4, 13, 'Porque eis que ele é que forma os montes, cria o vento, e informa seu pensamento ao ser humano; ele é o que torna a manhã em trevas, e pisa sobre as alturas da terra; EU-SOU, o Deus dos exércitos, é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 1, 'Ouvi esta palavra que eu levanto sobre vós, uma lamentação, ó casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 2, 'A virgem Israel caiu, não poderá mais se levantar; abandonada está sobre sua terra, ninguém há que a levante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 3, 'Porque assim diz o Senhor DEUS: A cidade que enviou mil [soldados] sobrará com cem; e a que enviou cem sobrará com dez, na casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 4, 'Porque assim diz o SENHOR à casa de Israel: Buscai-me, e vivereis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 5, 'Porém não busqueis a Betel nem venhais a Gilgal, nem passeis a Berseba; porque Gilgal será levada em cativeiro, e Betel será reduzida a nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 6, 'Buscai ao SENHOR, e vivereis; para que não aconteça que surja como fogo à casa de José, e a consuma, sem haver em Betel quem o apague.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 7, 'Vós perverteis o juízo em absinto, e abandonam a justiça no chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 8, 'Ele é o que fez as Plêiades e o Órion, e torna as trevas em manhã, e faz escurecer o dia em noite; ele chama as águas do mar, e as derrama sobre a face da terra; EU-SOU é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 9, 'Ele causa súbita destruição sobre o forte, e torna em ruínas a fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 10, 'Na porta da cidade eles odeiam ao que repreende, e abominam ao que fala com justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 11, 'Portanto, visto que pisoteais ao pobre e tomais dele um carga de trigo; assim edificastes casas de pedras lavradas, mas não habitareis nelas; plantastes belas vinhas, mas não bebereis o vinho delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 12, 'Pois sei que vossas transgressões são muitas e vossos pecados são grandes; afligis o justo, e recebeis suborno, e negam o direito dos necessitados na porta da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 13, 'Por isso o prudente em tal tempo fica calado, porque é um tempo mau.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 14, 'Buscai o bem, e não o mal, para que vivais; e assim o SENHOR Deus dos exércitos estará convosco, como dizeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 15, 'Odiai o mal, amai o bem, e praticai justiça na porta da cidade; talvez o SENHOR Deus dos exércitos tenha piedade do restante [do povo] de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 16, 'Portanto assim diz o SENHOR Deus dos exércitos, o Senhor: Em todas as praças haverá pranto, e em todas as ruas dirão: Ai! ai! E chamarão o lavrador ao choro, e os que sabem prantear ao lamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 17, 'E em todas as vinhas haverá pranto, porque passarei por meio de ti,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 18, 'Ai dos que desejam o dia do SENHOR! Para que quereis este dia do SENHOR? Será trevas, e não luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 19, 'Será como se alguém fugisse do leão, e o urso se encontrasse com ele; ou como se entrasse em alguma casa e apoiasse sua mão à parede, e fosse picado por uma cobra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 20, 'Por acaso não será o dia do SENHOR trevas e não luz, uma escuridão sem claridade alguma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 21, 'Eu odeio, desprezo vossas solenidades, e não aguento vossas reuniões religiosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 22, 'Ainda que me ofereçais holocaustos e vossas ofertas de alimentos, não os aceitarei; nem darei atenção a vossas ofertas de gratidão de vossos animais cevados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 23, 'Afasta de mim os teus muitos cânticos; também não ouvirei as melodias de teus instrumentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 24, 'Em vez disso, corra o juízo como as águas, e a justiça como um ribeiro impetuoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 25, 'Por acaso vós oferecestes a mim sacrifícios e ofertas de alimento no deserto durante os quarenta anos, ó casa de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 26, 'Em vez disso, levastes as imagens de vosso rei Sicute, e de Quium, a estrela de vossos deus, que fizestes para vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 5, 27, 'Portanto eu vos levarei cativos, para além de Damasco, diz o SENHOR, cujo nome é Deus dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 1, 'Ai dos que estão tranquilos em Sião, e dos que se sentem seguros no monte de Samaria, que são os príncipes da principal das nações, aos quais o povo de Israel vem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 2, 'Passai a Calné, e vede; e dali ide à grande Hamate; depois descei a Gate dos filisteus; por acaso são aqueles reinos melhores que estes, ou seu território maior que vosso território?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 3, 'Vós que pensais estar distante o dia mau, e aproximais o assento da violência;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 4, 'Eles se deitam em camas de marfim, e se estendem sobre seus leitos; comem os cordeiros do rebanho, e os bezerros de em meio do curral;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 5, 'Cantam ao som da harpa, e inventam para si instrumentos musicais, como Davi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 6, 'Bebem vinho em tigelas, e se ungem com o óleo mais valioso; mas não se afligem pela ruína de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 7, 'Por isso agora serão os primeiros a serem levados presos ao cativeiro, e o banquete dos que vivem no conforto se acabará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 8, 'O Senhor DEUS jurou por si mesmo; o SENHOR Deus dos exércitos diz: Eu abomino a arrogância de Jacó, e odeio seus palácios; por isso entregarei a cidade e tudo que ela tem [ao inimigo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 9, 'E acontecerá que, se dez homens restarem em uma casa, mesmo eles morrerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 10, 'E quando seu parente vier para queimar [os cadáveres] ,para tirar os ossos de casa, então dirá ao que estiver dentro da da casa: Há ainda alguém contigo? E ele responderá: Não. Então aquele dirá: Cala-te! Não menciones o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 11, 'Porque eis que o SENHOR mandará, e ferirá a casa maior com quebrantamento, e a casa menor com despedaçamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 12, 'Por acaso correm os cavalos pelos rochedos? Pode-se arar [ali] com bois? Porém vós pervertestes o juízo em veneno, e o fruto da justiça no amargo absinto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 13, 'Vós que vos alegrais por nada, que dizeis: Não conquistamos Carnaim por nossa própria força?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 6, 14, 'Diz o SENHOR Deus dos exércitos: Pois eis que eu levantarei contra vós, ó casa de Israel, uma nação que vos oprimirá desde a entrada de Hamate até o ribeiro de Arabá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 1, 'Assim o Senhor DEUS me fez ver: eis que ele formava gafanhotos, no começo do crescimento da plantação tardia; e eis que era a plantação tardia, depois da colheita do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 2, 'E aconteceu que, quando eles terminaram de comer a plantação da terra, eu disse: Senhor DEUS, perdoa, por favor; como Jacó poderá sobreviver? Pois é pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 3, '[Então] o SENHOR se arrependeu disso: Isto não acontecerá,disse o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 4, 'Assim o Senhor DEUS me fez ver: eis que o Senhor DEUS pretendeu executar juízo com fogo; e consumiu um grande abismo, assim como consumiu uma parte da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 5, 'Então eu disse: Senhor DEUS, cessa, por favor; como Jacó poderá sobreviver? Pois é pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 6, '[E] o SENHOR se arrependeu disso: Isto também não acontecerá, disse o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 7, 'Assim ele me fez ver: Eis que o Senhor estava sobre um muro que havia sido feito conforme o prumo, e havia um prumo em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 8, 'E o SENHOR me disse: O que vês, Amós? E eu disse: Um prumo. Então o Senhor disse: Eis que eu porei um prumo no meio de meu povo Israel; não mais o tolerarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 9, 'E os altos de idolatria de Isaque serão arruinados, e os santuários de Israel serão arruinados; e me levantarei com espada contra a casa de Jeroboão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 10, 'Então Amazias, o sacerdote de Betel, mandou mensagem a Jeroboão, rei de Israel, dizendo: Amós tem conspirado contra ti no meio da casa de Israel; esta terra não poderá suportar todas as suas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 11, 'Porque assim diz Amós: Jeroboão morrerá a espada, e Israel certamente será levado de sua terra em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 12, 'Depois Amazias disse a Amós: Vidente, vai embora, e foge para a terra de Judá, e ali come o teu pão, e ali profetiza;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 13, 'Porém não profetizes mais em Betel, porque ali estão o santuário do rei, e o palácio real.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 14, 'Então Amós respondeu a Amazias: Eu não era profeta, nem filho de profeta; mas eu era criador de gado, e colhedor de frutos de sicômoros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 15, 'Porém o SENHOR me tomou do trabalho com o gado, e o SENHOR me disse: Vai, e profetiza a meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 16, 'Agora pois, ouve a palavra do SENHOR. Tu dizes: Não profetizes contra Israel, nem fales contra a casa de Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 7, 17, 'Por isso, assim diz o SENHOR: Tua mulher se prostituirá na cidade, teus filhos e tuas filhas cairão à espada, e tua terra será repartida; tu morrerás em uma terra impura, e Israel será levado cativo de sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 1, 'Assim o SENHOR me fez ver: eis um cesto com frutos de verão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 2, 'E ele disse: O que vês, Amós? E eu disse: Um cesto com frutos de verão. Então o SENHOR me disse: Chegou o fim sobre meu povo Israel; não mais o tolerarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 3, 'E os cânticos do templo serão gemidos naquele dia,diz o Senhor DEUS; os cadáveres serão muitos, em todo lugar serão lançados. Silêncio!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 4, 'Ouvi isto, vós que tragais os necessitados, e arruinais os pobres da terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 5, 'Dizendo: Quando passará a lua nova, para vendermos o alimento? E o sábado, para abriremos os depósitos de trigo, e diminuirmos a medida, aumentarmos o preço, e fraudarmos com balanças enganosas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 6, 'Para comprarmos os pobres por dinheiro, e os necessitados por um par de sapatos, e venderemos os refugos do trigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 7, 'O SENHOR jurou pela glória de Jacó: Eu nunca me esquecerei das obras deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 8, 'A terra não se abalará por causa disto, e todo habitante dela não chorará? Certamente ela se levantará como um rio, se agitará, e se afundará como o rio do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 9, 'E será naquele dia,diz o Senhor DEUS, que farei o sol se pôr ao meio-dia, e escurecerei a terra no dia claro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 10, 'E tornarei vossas festas em luto, e todas as vossas canções em pranto; e farei com que todos se vistam de saco, e se façam calvas sobre todas as cabeças; e farei com que haja luto como de um filho único, e seu fim será como um dia amargo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 11, 'Eis que vêm dias,diz o Senhor DEUS, nos quais enviarei fome à terra; fome não de pão, nem sede de água, mas sim de ouvir as palavras do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 12, 'E irão sem rumo de mar a mar, do norte até o oriente; correrão de um lado para o outro em busca da palavra do SENHOR, mas não a encontrarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 13, 'Naquele tempo as belas virgens e os rapazes desmaiarão de sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 8, 14, 'Quanto aos que juram pelo pecado de Samaria, e dizem: Vive o teu deus de Dã; e: Vive o caminho de Berseba; esses cairão, e nunca mais se levantarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 1, 'Vi o Senhor que estava sobre o altar, e disse: Fere o topo das colunas, para que se estremeçam os umbrais; despedaça-os sobre as cabeça de todos; e os últimos deles matarei à espada; não haverá entre eles que fuja, nem quem se livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 2, 'Ainda que cavassem até o Xeol, dali minha mão os tirará; e se subissem até o céu, dali os farei descer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 3, 'E se se escondessem no topo do Carmelo, ali eu os buscaria e os tomaria; e ainda que se escondessem de diante de meus olhos no fundo do mar, até ali mandia uma serpente para os morder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 30, 'Amós', 'Am', 9, 4, 'E se forem levados em cativeiro diante de seus inimigos, ali mandarei a espada que os matará; e porei meus olhos sobre eles para o mal, e não para o bem.')
